ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

def convert(a, b, digits):
    if any((type(x) is not int or not 2 <= x <= 36 for x in (a, b))) or type(digits) is not str or (not 1 <= len(digits) <= 60):
        raise ValueError('invalid radix input')
    if any((ch not in ALPHABET + ALPHABET.lower() for ch in digits)):
        raise ValueError('invalid digit')
    value = 0
    for ch in digits.upper():
        if ch not in ALPHABET or ALPHABET.index(ch) >= a:
            raise ValueError('invalid digit')
        value = value * a + ALPHABET.index(ch)
    if value == 0:
        return '0'
    out = []
    while value:
        (value, remainder) = divmod(value, b)
        out.append(ALPHABET[remainder])
    return ''.join(reversed(out))
print(convert(16, 2, '00aF'))
print(convert(2, 36, '0000'))
print(convert(36, 10, 'Z'))
print(type(convert(10, 2, '10')).__name__)
try:
    convert(2, 10, '2')
except ValueError as error:
    print(error)

#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;

string convert(int a, int b, const string& digits) {
    const string alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (a < 2 || a > 36 || b < 2 || b > 36 || digits.empty() || digits.size() > 60)
        throw invalid_argument("invalid radix input");
    vector<int> current;
    for (char ch : digits) {
        if (ch >= 'a' && ch <= 'z') ch = char(ch - 'a' + 'A');
        auto pos = alphabet.find(ch);
        if (pos == string::npos || int(pos) >= a) throw invalid_argument("invalid digit");
        if (!current.empty() || pos != 0) current.push_back(int(pos));
    }
    if (current.empty()) return "0";
    string output;
    while (!current.empty()) {
        vector<int> quotient;
        int carry = 0;
        for (int digit : current) {
            int combined = carry * a + digit;  // <=1295, not the whole integer
            int next = combined / b;
            carry = combined % b;
            if (!quotient.empty() || next != 0) quotient.push_back(next);
        }
        output.push_back(alphabet[carry]);
        current.swap(quotient);
    }
    reverse(output.begin(), output.end());
    return output;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    if (!(cin >> q)) return 0;
    while (q--) {
        int a, b;
        string digits;
        cin >> a >> b >> digits;
        cout << convert(a, b, digits) << '\n';
    }
}
